        public static readonly string[] Codes = { "es", "pt", "fr", "de", "it", "tr", "ru", "pl", "id", "nl" };
        public static readonly string[] Names = { "Español (Spanish)", "Português (Portuguese)", "Français (French)", "Deutsch (German)", "Italiano (Italian)", "Türkçe (Turkish)", "Русский (Russian)", "Polski (Polish)", "Bahasa Indonesia (Indonesian)", "Nederlands (Dutch)" };

        public static Dictionary<string, string> Get(string code)
        {
            int col = Array.IndexOf(Codes, code);
            Dictionary<string, string> d = new Dictionary<string, string>();
            if (col < 0) return d;
            foreach (KeyValuePair<string, string[]> kv in Rows) d[kv.Key] = kv.Value[col];
            return d;
        }

